function a(t){if(t==null||t==="")return"—";const r=typeof t=="string"?parseFloat(t):t;return isNaN(r)?"—":new Intl.NumberFormat("en-IN",{style:"currency",currency:"INR",minimumFractionDigits:2,maximumFractionDigits:2}).format(r)}function s(t){if(!t)return"—";const r=typeof t=="string"?new Date(t):t;if(isNaN(r.getTime()))return"—";const n=String(r.getDate()).padStart(2,"0"),e=["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"][r.getMonth()],i=r.getFullYear();return`${n}-${e}-${i}`}export{s as a,a as f};
